    CONSTRAINT probleme_source_check CHECK (((source)::text = ANY (ARRAY[('outil'::character varying)::text, ('ia'::character varying)::text, ('humain'::character varying)::text]))),
    CONSTRAINT probleme_statut_check CHECK (((statut)::text = ANY (ARRAY[('nouveau'::character varying)::text, ('a_analyser'::character varying)::text, ('confirme'::character varying)::text, ('faux_positif'::character varying)::text, ('en_cours'::character varying)::text, ('a_tester'::character varying)::text, ('teste'::character varying)::text, ('termine'::character varying)::text, ('rouvert'::character varying)::text])))
