--
-- Name: v_decisions_correction; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_decisions_correction AS
 SELECT p.application_id,
    d.type_decision,
    count(*) AS nb
   FROM (public.decision_correction d
     JOIN public.probleme p ON ((p.id = d.probleme_id)))
  GROUP BY p.application_id, d.type_decision;


--
-- Name: v_evolution_problemes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_evolution_problemes AS
 SELECT application_id,
    date_trunc('month'::text, cree_le) AS mois,
    count(*) AS nb_crees
   FROM public.probleme
  GROUP BY application_id, (date_trunc('month'::text, cree_le));


--
-- Name: v_faux_positifs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_faux_positifs AS
 SELECT application_id,
    categorie,
    count(*) AS nb_total,
    count(*) FILTER (WHERE ((statut)::text = 'faux_positif'::text)) AS nb_faux_positifs,
    round(((100.0 * (count(*) FILTER (WHERE ((statut)::text = 'faux_positif'::text)))::numeric) / (count(*))::numeric), 1) AS taux_pct
   FROM public.probleme
  GROUP BY application_id, categorie;


--
-- Name: v_problemes_par_gravite; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_problemes_par_gravite AS
 SELECT application_id,
    categorie,
    gravite,
    statut,
    count(*) AS nb
   FROM public.probleme
  GROUP BY application_id, categorie, gravite, statut;


--
-- Name: v_problemes_rouverts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_problemes_rouverts AS
 SELECT p.application_id,
    count(*) AS nb_reouvertures,
    count(DISTINCT p.id) AS nb_problemes_concernes
   FROM (public.historique_statut h
     JOIN public.probleme p ON ((p.id = h.element_id)))
  WHERE (((h.type_element)::text = 'probleme'::text) AND ((h.nouveau_statut)::text = 'rouvert'::text))
  GROUP BY p.application_id;


--
-- Name: v_taches_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_taches_stats AS
 SELECT application_id,
    statut,
    count(*) AS nb,
    count(*) FILTER (WHERE ((echeance < CURRENT_DATE) AND ((statut)::text <> ALL (ARRAY[('terminee'::character varying)::text, ('arretee'::character varying)::text])))) AS nb_en_retard
   FROM public.tache
  GROUP BY application_id, statut;


--
-- Name: v_temps_resolution; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_temps_resolution AS
 SELECT p.id AS probleme_id,
    p.application_id,
    p.categorie,
    p.gravite,
    p.cree_le,
    h.termine_le,
    (h.termine_le - p.cree_le) AS duree
   FROM (public.probleme p
     JOIN LATERAL ( SELECT max(historique_statut.cree_le) AS termine_le
           FROM public.historique_statut
          WHERE (((historique_statut.type_element)::text = 'probleme'::text) AND (historique_statut.element_id = p.id) AND ((historique_statut.nouveau_statut)::text = 'termine'::text))) h ON ((h.termine_le IS NOT NULL)));


--
-- Name: v_temps_moyen_resolution; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_temps_moyen_resolution AS
 SELECT application_id,
    categorie,
    gravite,
    count(*) AS nb_resolus,
    avg(duree) AS duree_moyenne
   FROM public.v_temps_resolution
  GROUP BY application_id, categorie, gravite;


--
-- Name: v_utilite_solutions_ia; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_utilite_solutions_ia AS
 SELECT p.application_id,
    r.utilite_percue,
    count(*) AS nb
   FROM (((public.retour_solution r
     JOIN public.solution s ON ((s.id = r.solution_id)))
     JOIN public.diagnostic dg ON ((dg.id = s.diagnostic_id)))
     JOIN public.probleme p ON ((p.id = dg.probleme_id)))
  GROUP BY p.application_id, r.utilite_percue;


--
-- Name: v_validation_par_decision; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_validation_par_decision AS
 SELECT s.application_id,
    d.type_decision,
    count(*) FILTER (WHERE ((s.statut)::text = 'valide'::text)) AS nb_valides,
    count(*) FILTER (WHERE ((s.statut)::text = 'non_valide'::text)) AS nb_non_valides,
    count(*) FILTER (WHERE ((s.statut)::text = ANY (ARRAY[('a_tester'::character varying)::text, ('en_cours'::character varying)::text]))) AS nb_en_attente
   FROM (public.session_test s
     JOIN public.decision_correction d ON ((d.id = s.decision_id)))
  GROUP BY s.application_id, d.type_decision;


--
-- Name: v_validation_tests; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_validation_tests AS
 SELECT application_id,
    count(*) FILTER (WHERE ((statut)::text = 'valide'::text)) AS nb_valides,
    count(*) FILTER (WHERE ((statut)::text = 'non_valide'::text)) AS nb_non_valides,
    count(*) FILTER (WHERE ((statut)::text = ANY (ARRAY[('a_tester'::character varying)::text, ('en_cours'::character varying)::text]))) AS nb_en_attente,
    round(((100.0 * (count(*) FILTER (WHERE ((statut)::text = 'valide'::text)))::numeric) / (NULLIF(count(*) FILTER (WHERE ((statut)::text = ANY (ARRAY[('valide'::character varying)::text, ('non_valide'::character varying)::text]))), 0))::numeric), 1) AS taux_validation_pct
   FROM public.session_test
  GROUP BY application_id;


--
-- Name: verification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verification (
    id bigint NOT NULL,
    application_id bigint NOT NULL,
    depot_id bigint,
    branche character varying(100) DEFAULT 'develop'::character varying NOT NULL,
    commit_analyse character varying(64),
    perimetre text,
    declenchee_par bigint NOT NULL,
    type character varying(20) DEFAULT 'a_la_demande'::character varying NOT NULL,
    statut character varying(20) DEFAULT 'en_attente'::character varying NOT NULL,
    motif_echec text,
    avec_interpretation_ia boolean DEFAULT true NOT NULL,
    resultat_global character varying(30),
    debut_le timestamp with time zone DEFAULT now() NOT NULL,
    fin_le timestamp with time zone,
    CONSTRAINT verification_statut_check CHECK (((statut)::text = ANY (ARRAY[('en_attente'::character varying)::text, ('en_cours'::character varying)::text, ('terminee'::character varying)::text, ('echouee'::character varying)::text]))),
    CONSTRAINT verification_type_check CHECK (((type)::text = 'a_la_demande'::text))
);


